{"__advancedHuntingSettings":true,"query":"let I = IdentityInfo | summarize arg_max(Timestamp, *) by AccountObjectId | where Tags has "Sensitive";
I | summarize Value = count() | extend Metric = "Sensitive identities", Description = "MDI-flagged privileged/sensitive accounts", Sort = 0
| union (I | summarize Value = countif(IsAccountEnabled) | extend Metric = "Enabled", Description = "Active sensitive accounts", Sort = 1)
| union (I | summarize Value = countif(RiskLevel in ("High", "Medium")) | extend Metric = "At risk", Description = "Sensitive accounts at medium/high risk", Sort = 2)
| order by Sort asc
| project Metric, Value, Description","selectedWorkspaceIds":["e34d562e-ef12-4c4e-9bc0-7c6ae357c015"]}

{"__advancedHuntingSettings":true,"query":"let sensitive = IdentityInfo | summarize arg_max(Timestamp, *) by AccountObjectId | where Tags has "Sensitive" | distinct AccountUpn;
let mdi = AlertInfo | where Timestamp > ago(30d) and ServiceSource == "Microsoft Defender for Identity" | distinct AlertId;
AlertEvidence
| where Timestamp > ago(30d) and EntityType == "User" and AccountUpn in (sensitive)
| join kind=inner mdi on AlertId
| summarize Alerts = dcount(AlertId) by Account = AccountUpn
| order by Alerts desc
| take 15","selectedWorkspaceIds":["e34d562e-ef12-4c4e-9bc0-7c6ae357c015"]}

{"__advancedHuntingSettings":true,"query":"let ht = IdentityInfo | summarize arg_max(Timestamp, *) by AccountObjectId | where Tags has "Honeytoken" | distinct AccountUpn;
IdentityLogonEvents
| where Timestamp > ago(30d) and AccountUpn in (ht)
| summarize Attempts = count(), LastSeen = max(Timestamp) by Honeytoken = AccountUpn, IPAddress, ActionType
| order by Attempts desc
| take 20","selectedWorkspaceIds":["e34d562e-ef12-4c4e-9bc0-7c6ae357c015"]}
